const ini=()=>{const w=S.col.replace(/^Colegio /,'').split(' ').filter(x=>!['de','del','la','el','los','las'].includes(x.toLowerCase()));return(w.length>1?w[0][0]+w[1][0]:w[0].slice(0,2)).toUpperCase()};
function bdays(){const t=new Date();t.setHours(0,0,0,0);return S.cum.map((c,i)=>{const d=new Date(t.getFullYear(),+c[3].slice(0,2)-1,+c[3].slice(3));if(d<t)d.setFullYear(t.getFullYear()+1);const em=c[1]==='Docente'?c[0].replace(/^(Prof\.|Lic\.) /,'').toLowerCase().split(' ')[0]+'@'+S.dom:(F(c[2]).em||'');return{n:c[0],t:c[1],r:c[2],f:c[3],a:c[4],i,em,dias:Math.round((d-t)/864e5)}}).sort((x,y)=>x.dias-y.dias)}
function tgB(i){S.cum[i][4]^=1;V.email()}
function addAct(){const n=$('an').value.trim(),d=$('af').value;if(!n||!d){return}S.act.push({f:d.slice(5),n,q:$('aq').value||'—',i:$('ai').value||'—',doc:[$('d1').checked&&'Fotos',$('d2').checked&&'Video',$('d3').checked&&'Live'].filter(Boolean)});S.ptab='act';V.plan()}
function atlClick(e){const r=e.currentTarget.getBoundingClientRect();S.atlSel=+$('aI').value;S.atl.push({i:S.atlSel,x:Math.round((e.clientX-r.left)/r.width*800),y:Math.round((e.clientY-r.top)/r.height*600),ref:$('aR').value.trim()||'Sin referencia',fmt:$('aF').value,est:$('aE').value});V.atl()}
