function csv(t){const L=t.split(/\r?\n/).filter(x=>x.trim()),d=L[0].includes(';')?';':',',H=L[0].split(d).map(x=>x.trim());return L.slice(1).map(l=>{const v=l.split(d),o={};H.forEach((h,i)=>o[h]=(v[i]||'').trim());return o})}
function upFam(){const f=$('xf').files[0],m=$('upmsg');if(!f){m.textContent='Primero selecciona un archivo.';return}
 const r=new FileReader();r.onerror=()=>{m.textContent='No se pudo leer el archivo.'};r.onload=e=>{let rows;try{
  if(window.XLSX){const wb=XLSX.read(e.target.result,{type:'array'});rows=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{defval:''})}
  else if(/\.csv$/i.test(f.name)){rows=csv(new TextDecoder().decode(e.target.result))}
  else{m.textContent='El lector de Excel no cargó. Prueba con un archivo .csv.';return}}catch(x){m.textContent='El archivo no se pudo interpretar. Revisa que sea un Excel válido.';return}
  const g=(o,ks)=>{for(const k in o){const n=k.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();if(ks.some(x=>n.includes(x)))return String(o[k]).trim()}return''};let c=0;
  rows.forEach(o=>{const n=g(o,['familia','alumno','apellido','nombre']);if(!n)return;const nn=/^familia/i.test(n)||!TM.pre?n:TM.pre+n,em=g(o,['correo','email','mail']);S.fam.push({n:nn,em,tel:g(o,['whatsapp','celular','telefono']),g:g(o,['grado','curso'])||'—',d:g(o,['distrito','urbaniz']),o:g(o,['origen'])||'Excel',e:0,ce:em?['Bienvenida','Pendiente']:null});S.animo.push([nn,3,'Sin encuesta aún']);c++});
  S.tab='lista';V.crm();$('upmsg').textContent=c?c+' familias cargadas desde '+f.name+'.':'No se encontraron familias. Revisa que la primera fila tenga los nombres de las columnas.'};
 r.readAsArrayBuffer(f)}
function feeds(){
 const L=S.links,hs=x=>[...x].reduce((a,c)=>(a*31+c.charCodeAt(0))>>>0,7),has=(u,d)=>u&&u.toLowerCase().includes(d),
 hn=u=>{try{return(new URL(/^https?:/i.test(u)?u:'https://'+u).pathname.split('/').filter(Boolean).pop()||'').replace(/^@/,'')}catch(e){return''}},
 pretty=h=>h.replace(/[._-]+/g,' ').replace(/\b\w/g,c=>c.toUpperCase()),
 iv=n=>{const w=n.split(' ').filter(x=>x&&!['de','del','la','el','los','las'].includes(x.toLowerCase()));return(w.length>1?w[0][0]+w[1][0]:(w[0]||'?').slice(0,2)).toUpperCase()},
 av=n=>`<div class="av">${iv(n)}</div>`,
 tile=(t,i,r,x)=>`<div style="aspect-ratio:${r||'1'};background:color-mix(in srgb,var(--red) ${10+i*4}%,#fff);border-radius:6px;padding:6px;font-size:10px;display:flex;flex-direction:column;justify-content:flex-end;font-weight:600">${t}${x?`<span class="note">▶ ${x}</span>`:''}</div>`,
 T=S.posts.map(p=>p.t).concat(S.ideas),
 mil=(h,a)=>(a+hs(h)%90/10).toFixed(1).replace('.',',')+' mil',
 ph=(n,d)=>`<div class="card prof" style="text-align:center;padding:30px 14px"><div style="margin-bottom:8px">${tg(n)}</div><p class="note">Pega el link de ${d} arriba y pulsa “Cargar feeds” para ver el perfil.</p></div>`;
 const fh=hn(L.fb),ih=hn(L.ig),th=hn(L.tt),fbN=fh&&!/\.php$/.test(fh)?pretty(fh):S.col;
 const form=`<div class="card" style="margin-bottom:12px"><h3>Links de las redes sociales de la institución</h3><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(240px,1fr))"><div><label>Facebook institucional:</label><input id="lf" value="${L.fb}" placeholder="https://facebook.com/tucolegio"></div><div><label>Instagram institucional:</label><input id="li" value="${L.ig}" placeholder="https://instagram.com/tucolegio"></div><div><label>TikTok institucional:</label><input id="lt" value="${L.tt}" placeholder="https://tiktok.com/@tucolegio"></div></div><button class="btn" style="margin-top:10px" onclick="saveLinks()">Cargar feeds</button>${[[L.fb,'facebook.com','Facebook'],[L.ig,'instagram.com','Instagram'],[L.tt,'tiktok.com','TikTok']].map(x=>x[0]&&!has(x[0],x[1])?` <span class="tag wn">El link de ${x[2]} no parece válido</span>`:'').join('')}</div>`;
 const fb=has(L.fb,'facebook.com')?`<div class="card prof"><div style="height:70px;border-radius:8px;background:linear-gradient(120deg,var(--red),color-mix(in srgb,var(--red) 45%,#fff));margin-bottom:-26px"></div><div style="display:flex;gap:10px;align-items:flex-end;padding:0 8px">${av(fbN)}<div><b>${fbN}</b><br><span class="note">Institución educativa</span></div></div><p class="note" style="margin:10px 8px">${mil(fh,8)} seguidores</p>${T.slice(0,2).map((t,i)=>`<div style="border-top:1px solid var(--bd);padding:10px 8px"><b>${t}</b><div style="margin:6px 0">${tile('',i,'16/9')}</div><span class="note">👍 124 · 💬 18 · ↗ 9</span></div>`).join('')}<div style="text-align:center;margin-top:6px">${tg('fb')}</div></div>`:ph('fb','Facebook');
 const ig=has(L.ig,'instagram.com')?`<div class="card prof"><div style="display:flex;gap:12px;align-items:center">${av(ih)}<div><b>@${ih}</b><br><span class="note">${mil(ih,5)} seguidores</span></div></div><p style="margin:10px 0"><b>${pretty(ih)}</b><br><span class="note">Perfil institucional · ${S.col}</span></p><div class="tiles">${T.slice(0,9).map((t,i)=>tile(t,i)).join('')}</div><div style="text-align:center;margin-top:8px">${tg('ig')}</div></div>`:ph('ig','Instagram');
 const tt=has(L.tt,'tiktok.com')?`<div class="card prof"><div style="display:flex;gap:12px;align-items:center">${av(th)}<div><b>@${th}</b><br><span class="note">${mil(th,3)} seguidores</span></div></div><p class="note" style="margin:10px 0">Videos de la vida escolar de ${S.col}.</p><div class="tiles">${T.slice(0,6).map((t,i)=>tile(t,i,'3/4',(12-i)+'k')).join('')}</div><div style="text-align:center;margin-top:8px">${tg('tt')}</div></div>`:ph('tt','TikTok');
 return form+`<div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(260px,1fr))">${fb}${ig}${tt}</div><p class="note" style="margin-top:10px">Vista previa simulada a partir del link. Para mostrar las publicaciones reales hay que conectar cada cuenta con la API oficial de la red.</p>`}
