function addPost(){const t=$('pt').value.trim();if(!t)return;const r=['fb','ig','tt'].filter(x=>$('r'+x).checked);S.posts.push({d:Math.min(30,Math.max(1,+$('pd').value||1)),t,r,s:'Pendiente'});V.redes()}
function idea(i){S.posts.push({d:10+i,t:S.ideas[i],r:['ig','fb'],s:'Borrador'});V.redes()}
function addCamp(){const n=$('cn').value.trim();if(!n)return;S.camp.push({n,c:$('cc').value,g:+$('cg').value||0,l:0,m:0,s:'Activa'});V.camp()}
function saveCfg(){S.cfg={matricula:+c1.value||0,pension:+c2.value||0,meses:+c3.value||0,anios:+c4.value||1,modo:c5.value};go('camp')}

(function(){
 const w=$('world');
 const add=(c,css,h,d)=>{const e=document.createElement('div');e.className='it '+c;e.style.cssText=css+';animation-delay:-'+d+'s';e.innerHTML=h;w.appendChild(e)};
 const cube=s=>{const h=s/2,f=['translateZ('+h+'px)','rotateY(180deg) translateZ('+h+'px)','rotateY(90deg) translateZ('+h+'px)','rotateY(-90deg) translateZ('+h+'px)','rotateX(90deg) translateZ('+h+'px)','rotateX(-90deg) translateZ('+h+'px)'];return '<div class="sp spin cb" style="width:'+s+'px;height:'+s+'px">'+f.map(t=>'<i style="transform:'+t+'"></i>').join('')+'</div>'};
 const ball=s=>'<div class="ball" style="width:'+s+'px;height:'+s+'px"></div>';
 const T=[[0,0],[74,0],[36,64],[110,64]];let L='';
 for(let z=-16;z<=16;z+=4)T.forEach(t=>L+='<b style="left:'+t[0]+'px;top:'+t[1]+'px;background:'+(z===16?'#FC3030':'hsl(0 85% '+(24+(z+16)*.9)+'%)')+';transform:translateZ('+z+'px)"></b>');
 add('hs','left:calc(6% - 22px);top:calc(16% - 55px);width:260px;height:260px','<div class="rs"><div class="ring"></div></div>',2);
 add('hs','left:6%;top:16%;scale:1.2','<div class="sp swy"><div class="lg3">'+L+'</div></div>',0);
 add('','right:10%;top:12%',cube(64),1);
 add('','left:15%;bottom:15%',cube(40),4);
 add('','right:19%;bottom:27%',cube(34),2);
 add('','right:6%;top:52%',ball(70),3);
 add('','left:31%;top:8%',ball(44),5);
 add('hs','left:5%;top:64%',ball(28),1);
 add('','right:31%;bottom:8%',ball(56),6);
 add('','right:3%;bottom:6%;width:210px;height:210px','<div class="rs"><div class="ring"></div></div>',4);
 $('login').addEventListener('mousemove',e=>{const x=e.clientX/innerWidth-.5,y=e.clientY/innerHeight-.5;w.style.transform='rotateY('+(x*14)+'deg) rotateX('+(-y*10)+'deg)'});
})();

